package checks;
import dev.zomboid.isotacz.*;import net.minecraft.client.Minecraft;import net.minecraft.world.phys.Vec3;import checks.Checks.*;
public class RoomChecks{
 static int count;static void ok(boolean b,String why){count++;if(!b)throw new AssertionError(why);}
 public static class Original{public int calls;public Object call(Object... args){calls++;return ((Camera)args[0]).getPosition();}}
 static boolean sameRoom(Vec3 source,Vec3 ear){return source.x()<10&&ear.x()<10;}
 public static void main(String[]a){Minecraft mc=Minecraft.INSTANCE;Bridge.iso=true;mc.player=new Player();Camera cam=new Camera();Executor ex=new Executor();Listener l=new Listener();CI ci=new CI();PlayerAudio31.update(cam,true,l,ex,ci);Original original=new Original();Vec3 source=new Vec3(2,65,3);Vec3 ears=(Vec3)PlayerAudio31.acoustics(cam,original);ok(!sameRoom(source,cam.pos),"old camera endpoint is outside room");ok(sameRoom(source,ears),"new acoustic endpoint is inside player room");ok(original.calls==0,"detached camera not consulted in iso");mc.player.eyes=new Vec3(99,99,99);ex.queued.run();ok(l.transform.position().equals(ears),"acoustics and audio executor use identical immutable snapshot");
 for(float pitch:new float[]{-75,0,75})for(float yaw:new float[]{-180,-90,0,90,180}){mc.player.pitch=pitch;mc.player.yaw=yaw;PlayerAudio31.update(cam,true,l,ex,new CI());ex.queued.run();ok(l.transform.position().equals(PlayerAudio31.point(cam)),"orientation never changes ear anchor");}
 mc.level=new Object();mc.player.eyes=new Vec3(4,65,4);ok(PlayerAudio31.point(cam).equals(mc.player.getEyePosition(.25f)),"old world snapshot rejected");Bridge.iso=false;ok(PlayerAudio31.point(cam)==cam.pos,"first person and vanilla cameras unchanged");ok(PlayerAudio31.acoustics(cam,original)==cam.pos&&original.calls==1,"original operation invoked outside iso");Bridge.iso=true;mc.player=null;ok(PlayerAudio31.acoustics(cam,original)==cam.pos&&original.calls==2,"no player fallback");System.out.println("ROOM_AUDIO_CHECKS="+count);}}
